// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address caller, uint256 amount, bytes memory data) public {
        vm.assume(caller != address(0));
        amount = bound(amount, 0, 1 ether);

        vm.deal(address(c), 1 ether);

        vm.deal(caller, 1 ether);

        bool ok;
        if (caller == address(this)) {
            try c.sendMoney(address(0xdead), amount, data) {
                ok = true;
            } catch {
                ok = false;
            }
            assertTrue(ok);
        } else {

            try c.sendMoney(caller, amount, data) {
                ok = true;
            } catch {
                ok = false;
            }
            assertTrue(ok);
        }
    }
}
